from pathlib import Path
import json,html,datetime
R=Path(__file__).parent
S=json.loads((R/'data/sources.json').read_text(encoding='utf-8'))
P=json.loads((R/'data/wiki_pages.json').read_text(encoding='utf-8'))
D=json.loads((R/'data/slides.json').read_text(encoding='utf-8'))
Q={'before':json.loads((R/'logs/qa_before.json').read_text(encoding='utf-8'))['checks'], 'after':json.loads((R/'logs/qa_after.json').read_text(encoding='utf-8'))['checks']} if (R/'logs/qa_after.json').exists() else {}
H=lambda x:html.escape(str(x),quote=True)

def layout(name,body,active=''):
    nav=''.join(f'<a href="{t}.html" class="{"active" if active==t else ""}">{label}</a>' for t,label in [('index','首頁'),('wiki','知識 Wiki'),('slides','教學簡報'),('workflow','工作流程')])
    return f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b1021"><title>{H(name)} | RAG ATLAS</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><a class="logo" href="index.html"><span class="logo-symbol">◈</span> RAG ATLAS <span style="color:var(--soft);font-weight:500;font-size:11px">LLM WIKI PROJECT</span></a><nav class="navlinks">{nav}</nav></header>{body}<footer class="footer"><div class="page-container footer-inner"><span>RAG ATLAS · LLM-assisted, source-traceable educational wiki</span><span>2026.11.22｜提供離線閱讀 · 引用請回原始來源查核</span></div></footer></body></html>'''

home='''<main class="page-container"><div class="hero"><section><div class="eyebrow">OPEN KNOWLEDGE PROJECT · 2026</div><h1>讓 AI 的回答<br><span class="accent">有跡可循。</span></h1><p>從 6 份可信資料出發，建立一個可搜尋、可追溯來源的 LLM Wiki，再把知識整理成適合新手的 14 頁互動 HTML 教學簡報。</p><div class="pill-row"><span class="pill"># 檢索增強生成 RAG</span><span class="pill"># 來源追溯</span><span class="pill"># Loop / Graph</span><span class="pill"># 可離線瀏覽</span></div><div class="actions"><a class="btn primary" href="slides.html">開始教學簡報 ↗</a><a class="btn secondary" href="wiki.html">瀏覽 Wiki 知識庫</a></div></section><div class="orbital glass" aria-label="RAG 檢索與生成的概念圖"><span class="orbit"></span><span class="orbit two"></span><div class="orb-core">RAG<br><span>ATLAS</span></div><span class="sat top">📚 知識庫</span><span class="sat right">🔎 檢索</span><span class="sat bottom">✨ 生成</span></div></div><section class="section"><div class="eyebrow">PROJECT OVERVIEW</div><h2 class="section-title">這份作業不是只做出漂亮的簡報</h2><p class="section-intro">它示範資料如何進入知識庫，如何整理出概念頁，最後如何確認投影片的每一句關鍵知識都能追溯。</p><div class="metric-grid"><div class="metric"><strong>06</strong><span>完成來源重點匯入（ingest）</span></div><div class="metric"><strong>09</strong><span>互相交叉連結的知識頁</span></div><div class="metric"><strong>14</strong><span>附 Wiki 對應與引用的教學投影片</span></div></div></section><section class="section"><div class="eyebrow">EXPLORE</div><h2 class="section-title">從資料一路看見產出</h2><div class="feature-grid"><a href="wiki.html" class="feature"><div class="feature-icon">📖</div><h3>LLM Wiki</h3><p>搜尋核心概念、看來源 S01–S06，並沿著內部關聯閱讀。</p><span class="accent">閱讀知識庫 →</span></a><a href="slides.html" class="feature"><div class="feature-icon">🖥️</div><h3>HTML 教學簡報</h3><p>用容易理解的校園案例，從問題、流程到評估一步步學習 RAG。</p><span class="accent">進入簡報 →</span></a><a href="workflow.html" class="feature"><div class="feature-icon">🔁</div><h3>Loop / Graph + QA</h3><p>查看節點、回圈條件、第一次檢查失敗與修正後的實測紀錄。</p><span class="accent">查看設計與測試 →</span></a></div></section><section class="section" style="padding-bottom:90px"><div class="glass" style="padding:32px"><div class="eyebrow">IMPORTANT NOTE</div><h2 style="margin:8px 0">這是可攜式、檔案式 LLM Wiki 成果</h2><p class="muted">使用 LLM 協助整理 6 份網頁／論文資訊並建立 Markdown Wiki；此網站展示整理好的知識、來源與流程。它不是即時連接外部模型的問答系統，也沒有宣稱已完成雲端 LLM Wiki 平台上的帳號匯入。原始連結可供再次查核。</p></div></section></main>'''
(R/'index.html').write_text(layout('首頁',home,'index'),encoding='utf-8')

wiki_ui='''<main class="page-container"><div class="wiki-wrap"><aside class="wiki-side"><div class="eyebrow">SEARCH THE WIKI</div><h3>知識索引</h3><input id="wiki-search" class="search" placeholder="搜尋：檢索、向量、評估…" aria-label="搜尋 Wiki 知識頁"><div class="wiki-menu" id="wiki-menu"></div><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><a class="btn secondary" href="#sources" id="all-sources-jump" style="display:block;text-align:center">檢視 6 份來源 ↗</a><div class="stats-inline" style="margin-top:18px"><span>9 篇概念頁</span><span>6 份資料</span></div></aside><article class="wiki-content glass" id="wiki-content" aria-live="polite"></article></div><section class="section" id="sources"><div class="eyebrow">SOURCE LEDGER</div><h2 class="section-title">已 ingest 的資料</h2><p class="section-intro">每份皆保留來源頁面連結與自撰摘要，可在專案 <code>sources/Sxx.md</code> 查閱。來源摘要不是原文全文。</p><div class="all-sources glass" id="source-ledger"></div></section></main>'''
wiki_script='''<script id="data-pages" type="application/json">__PAGES__</script><script id="data-sources" type="application/json">__SOURCES__</script><script>
const pages=JSON.parse(document.getElementById('data-pages').textContent),sources=JSON.parse(document.getElementById('data-sources').textContent);
const byId=Object.fromEntries(pages.map(p=>[p.id,p])),srcId=Object.fromEntries(sources.map(s=>[s.id,s]));
const menu=document.getElementById('wiki-menu'),panel=document.getElementById('wiki-content');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function current(){let h=location.hash.replace('#','');return byId[h]?h:'intro'}
function renderMenu(){const q=document.getElementById('wiki-search').value.trim().toLocaleLowerCase();const found=pages.filter(p=>[p.title,p.topic,p.lead,p.bullets.join(' '),p.example].join(' ').toLocaleLowerCase().includes(q));menu.innerHTML=found.map(p=>`<button class="${current()===p.id?'selected':''}" data-id="${p.id}">${esc(p.title)}<small>${esc(p.topic)}</small></button>`).join('')||'<p class="muted">找不到符合的條目</p>';menu.querySelectorAll('button').forEach(b=>b.onclick=()=>{location.hash=b.dataset.id;render()})}
function render(){const p=byId[current()];let citing=p.sources.map(id=>{let s=srcId[id];return `<div class="source-row"><strong>${id}</strong><a target="_blank" rel="noopener noreferrer" href="${esc(s.url)}">${esc(s.publisher)}｜${esc(s.title)}</a></div>`}).join('');panel.innerHTML=`<div class="eyebrow">WIKI ARTICLE · ${esc(p.topic)}</div><h1>${esc(p.title)}</h1><div class="stats-inline"><span>來源 ${p.sources.length} 份</span><span>延伸條目 ${p.related.length} 篇</span><span>可追溯</span></div><p class="lead">${esc(p.lead)}</p><h2>重點整理</h2><ul class="note-list">${p.bullets.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><h2>💡 初學者例子</h2><div class="example-box">${esc(p.example)}</div><h2>資料來源｜Source lineage</h2><div class="source-list">${citing}</div><h2>繼續探索</h2><div class="related">${p.related.map(id=>`<button data-id="${id}">${esc(byId[id].title)}</button>`).join('')}</div><p style="margin-top:35px"><a class="btn secondary" href="slides.html">從頭看教學簡報 ↗</a></p>`;panel.querySelectorAll('.related button').forEach(b=>b.onclick=()=>{location.hash=b.dataset.id;render();window.scrollTo({top:0,behavior:'smooth'})});renderMenu();}
window.addEventListener('hashchange',render);document.getElementById('wiki-search').addEventListener('input',renderMenu);render();document.getElementById('source-ledger').innerHTML=sources.map(s=>`<div><b class="accent">${s.id}</b> ｜ <a target="_blank" rel="noopener noreferrer" href="${esc(s.url)}">${esc(s.publisher)} — ${esc(s.title)}</a><div class="muted" style="margin-left:45px;font-size:12px">${esc(s.type)} · 來源摘要見專案 sources/${s.id}.md</div></div>`).join('');
</script>'''.replace('__PAGES__',json.dumps(P,ensure_ascii=False).replace('</','<\\/')).replace('__SOURCES__',json.dumps(S,ensure_ascii=False).replace('</','<\\/'))
wiki_html=layout('知識 Wiki',wiki_ui,'wiki').replace('</body>',wiki_script+'</body>')
(R/'wiki.html').write_text(wiki_html,encoding='utf-8')

# Slide builders
mini=lambda title,desc,ico='✦',color='':f'<div class="mini {color}"><div class="icon-big">{ico}</div><h3>{title}</h3><p>{desc}</p></div>'
def cards(*items,cols=3):return f'<div class="cardset cols{cols}">'+''.join(items)+'</div>'
def flow(*items):return '<div class="flowsteps">'+'<span class="flow-arrow">→</span>'.join(items)+'</div>'
def build_body(kind):
 if kind=='cover':return '<div class="cover-hero"><div><div class="eyebrow">RETRIEVAL · AUGMENTED · GENERATION</div><h2>讓 AI 先找資料，<br><span class="accent">再回答。</span></h2><p class="sub">一堂給 RAG 新手的 10 分鐘入門課</p><div class="pill-row"><span class="pill">📖 有來源</span><span class="pill">🧠 有流程</span><span class="pill">✅ 有驗證</span></div></div><div class="cover-art"><div class="glow"></div><span class="art-tag one">📄 原始文件</span><span class="art-tag two">🔎 找出證據</span><span class="art-tag three">✨ 生成答案</span></div></div>'
 if kind=='problem':return cards(mini('最新公告','模型訓練時可能還沒有這學期的公告。','🗓️','cyan'),mini('私有文件','你的系所或實驗室規定，不一定在公開訓練資料裡。','🔐','purple'),mini('信心不等於正確','答案說得流利，也可能沒有足夠證據。','⚠️','peach'))
 if kind=='definition':return '<div class="centered"><div class="bigword">RAG</div><div style="margin-top:18px;font-size:clamp(15px,2vw,28px)"> <span class="accent">找資料</span> ＋ <span class="violet">附上上下文</span> ＋ <span style="color:var(--coral)">生成回答</span></div><p class="muted" style="margin-top:26px">就像考試可以「先翻參考書，再用自己的話作答」；書就是外部知識庫。</p></div>'
 if kind=='pipeline':return flow(mini('1. Retrieve','先從知識庫找與提問有關的段落。','🔎','cyan'),mini('2. Augment','把問題與找到的段落一起交給模型。','🧩','purple'),mini('3. Generate','根據提供的證據，整理有來源的答案。','✨','peach'))
 if kind=='index':return flow(mini('來源文件','公告、規章、PDF','📄','cyan'),mini('切成段落','保留主題與脈絡','✂️','purple'),mini('建立索引','關鍵字／向量','🗂️','peach'))
 if kind=='search':return cards(mini('Keyword','適合精確名稱、編號、特定字詞。','🔤','cyan'),mini('Vector','搜尋語意相近的內容，不限完全相同的字。','🧭','purple'),mini('Hybrid','綜合關鍵字與向量訊號，提高找對資料的機會。','🔀','peach'))
 if kind=='example':return cards(mini('學生提問','「週日可以使用實驗室嗎？」','💬','cyan'),mini('檢索到公告','示意資料：<br>「週日不開放。」','📑','purple'),mini('回答並引用','「依示例公告，週日不開放。」<br><small>（示例，不代表任何真實校規）</small>','✅','peach'))
 if kind=='compare':return cards(mini('一般聊天','主要利用既有能力與當前對話；不保證知道新規定。','💬','cyan'),mini('RAG','回答時查詢外部文件，容易更新資料並附來源。','📚','purple'),mini('Fine-tuning','額外訓練模型來改變表現，不是每則公告更新的必要條件。','🛠️','peach'))
 if kind=='risks':return cards(mini('資料錯','公告過期、來源互相衝突。<br><b>→ 檢查版本與可信度</b>','🗓️','cyan'),mini('找錯','切塊遺失前後文，檢索到無關段落。<br><b>→ 檢查搜尋與 chunk</b>','🧩','purple'),mini('答錯','沒有證據卻過度推論。<br><b>→ 逐句核對引用</b>','⚠️','peach'))
 if kind=='evaluation':return cards(mini('檢索相關性','找到的片段真的能回答問題嗎？','🎯','cyan'),mini('忠實度','答案的每項主張，都能從證據推得嗎？','🧾','purple'),mini('來源可追溯','能點回原文？有版本、標題與網址嗎？','🔗','peach'))
 if kind=='checklist':return '<div class="timeline">'+''.join(mini(t,d,f'{i:02d}') for i,(t,d) in enumerate([('找可靠資料','確認來源與日期'),('切塊與建索引','保留脈絡、可搜尋'),('測試檢索','問題是否找到對的段落'),('依據生成','只用可用證據回答'),('回歸測試','檢查引用、矛盾與更新')],1))+'</div>'
 if kind=='quiz':return '<div style="width:100%"><p class="micro">題目：當學生提問時，哪一個最符合 RAG 的主要流程？</p><div class="quiz-options"><button data-correct="false">A. 問題 → 直接生成 → 搜尋資料</button><button data-correct="true">B. 問題 → 檢索文件 → 放入上下文 → 生成回答</button><button data-correct="false">C. 問題 → 重新訓練整個模型 → 生成回答</button></div><p id="quiz-result" aria-live="polite">選一個答案，立即看解釋。</p></div>'
 if kind=='summary':return cards(mini('① 先找證據','RAG 的價值從可檢索的知識庫開始。','🔎','cyan'),mini('② 根據證據','讓回答有根據、有引用，也知道何時說「不知道」。','💬','purple'),mini('③ 持續檢查','資料品質、檢索品質、生成忠實度都重要。','✅','peach'))
 if kind=='references':return '<div class="refs-grid">'+''.join(f'<div class="refline"><b class="accent">{s["id"]}</b>　<a href="{H(s["url"])}" target="_blank" rel="noopener noreferrer">{H(s["publisher"])}｜{H(s["title"])}</a></div>' for s in S)+'</div>'
 raise ValueError(kind)

sections=[]
for ix,d in enumerate(D):
 ids=' '.join(d['sources'])
 source_links=' · '.join(f'<a href="{H(next(s["url"] for s in S if s["id"]==v))}" target="_blank" rel="noopener noreferrer">{v}</a>' for v in d['sources'])
 wiki_links=' · '.join(f'<a href="wiki.html#{v}" target="_blank" rel="noopener">Wiki:{v}</a>' for v in d['wiki'])
 if d['kind']=='cover':heading=''
 else: heading=f'<h2>{H(d["title"])}</h2><p class="sub">{H(d["sub"])}</p>'
 sections.append(f'<section class="slide {"active" if ix==0 else ""}" data-index="{ix}" data-kind="{H(d["kind"])}" data-source-ids="{ids}" aria-label="第 {ix+1} 張：{H(d["title"])}"><div class="slide-top">{H(d["eyebrow"])}</div>{heading}<div class="slide-main">{build_body(d["kind"])}</div><div class="sources-small">來源：{source_links}　｜　{wiki_links}</div><span class="slidenum">{ix+1:02d} / {len(D):02d}</span></section>')
deck='''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b1021"><title>RAG 從零開始｜14 頁教學簡報</title><link rel="stylesheet" href="assets/style.css"></head><body class="deck-body"><div class="deck-shell"><div class="deckbar"><a href="index.html" class="logo"><span class="logo-symbol">◈</span> RAG ATLAS <span class="muted" style="font-size:11px">TEACHING DECK</span></a><div class="deck-nav"><a href="wiki.html" target="_blank">查看 Wiki ↗</a><button id="prev" class="roundbtn" aria-label="上一張">←</button><span id="counter" style="min-width:48px;text-align:center">01 / 14</span><button id="next" class="roundbtn" aria-label="下一張">→</button><button id="fullscreen" class="roundbtn" aria-label="切換全螢幕">⛶</button></div></div><main class="stage">__SLIDES__</main><div class="deck-bottom"><span>← → / 空白鍵切換</span><div class="progress" id="progress" aria-label="簡報進度"><div class="progress-fill" id="progress-fill"></div></div><span>每張附資料來源</span></div></div>
<script>
const slides=[...document.querySelectorAll('.slide')];let index=0;let touchX=0;
function show(n){index=Math.max(0,Math.min(slides.length-1,n));slides.forEach((el,i)=>{el.classList.toggle('active',i===index);el.setAttribute('aria-hidden',String(i!==index))});document.getElementById('counter').textContent=String(index+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0');document.getElementById('progress-fill').style.width=((index+1)/slides.length*100)+'%';document.getElementById('prev').disabled=index===0;document.getElementById('next').disabled=index===slides.length-1;location.hash='slide-'+(index+1)}
document.getElementById('prev').onclick=()=>show(index-1);document.getElementById('next').onclick=()=>show(index+1);document.getElementById('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.()};
document.addEventListener('keydown',e=>{if(['ArrowRight',' ','PageDown'].includes(e.key)){e.preventDefault();show(index+1)}else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(index-1)}else if(e.key==='Home'){show(0)}else if(e.key==='End'){show(slides.length-1)}});
document.getElementById('progress').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();show(Math.floor((e.clientX-r.left)/r.width*slides.length))};document.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].screenX},{passive:true});document.addEventListener('touchend',e=>{let dx=e.changedTouches[0].screenX-touchX;if(Math.abs(dx)>70)show(index+(dx<0?1:-1))},{passive:true});
document.querySelectorAll('.quiz-options button').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.quiz-options button').forEach(b=>b.classList.remove('correct','wrong'));const correct=btn.dataset.correct==='true';btn.classList.add(correct?'correct':'wrong');document.getElementById('quiz-result').textContent=correct?'✓ 正確！先 Retrieve，再 Augment，最後 Generate。':'再想想：RAG 不一定需要重新訓練，且通常先檢索、再生成。';});
const match=location.hash.match(/slide-(\\d+)/);show(match?Number(match[1])-1:0);
</script></body></html>'''
(R/'slides.html').write_text(deck.replace('__SLIDES__',''.join(sections)),encoding='utf-8')

report='''<main class="page-container flow-wrap"><section class="flow-header"><div class="eyebrow">GRAPH / LOOP DESIGN</div><h1 class="section-title" style="font-size:clamp(38px,5vw,62px)">從六份資料到<br><span class="accent">一堂能驗證的課。</span></h1><p class="section-intro">本頁紀錄整個資料處理流程，包含哪些節點會重複、哪些節點會失敗回退，以及一次故障注入測試與修正紀錄。</p></section><section class="section"><h2 class="section-title">01 / Workflow Graph</h2><div class="graph-panel glass"><div class="flowchart"><div class="node"><b>01 · DISCUSS</b><p>定義初學者目標、範圍與內容架構</p></div><div class="node"><b>02 · INGEST</b><p>逐份讀取 6 個原始來源、生成摘要卡</p></div><div class="node"><b>03 · VALIDATE SOURCE</b><p>確認主題、來源 URL 與可支持的主張</p></div><div class="node"><b>04 · WIKI BUILD</b><p>整合成 9 個概念頁與交叉連結</p></div><div class="node"><b>05 · QUERY WIKI</b><p>按教學問題尋找有引用的 Wiki 頁</p></div><div class="node"><b>06 · SLIDE OUTLINE</b><p>安排動機、原理、案例、檢查與測驗</p></div><div class="node"><b>07 · SOURCE AUDIT</b><p>逐張核對 Wiki refs 與 source IDs</p></div><div class="node return"><b>08 · RENDER & TEST</b><p>產生 HTML，測試按鍵、跳轉與來源</p></div></div><div class="loop-explain"><b>↩ 迴圈與回退條件</b><p>① 每新增一份資料，就重做來源檢查與 Wiki 更新。② 查到資訊不足，就返回 INGEST 補來源。③ 若投影片引用與 Wiki 不一致，退回「SOURCE AUDIT / SLIDE OUTLINE」修正。④ 若 HTML 有壞連結或按鍵失效，退回 RENDER 再測。</p></div></div></section><section class="section"><h2 class="section-title">02 / 一次實際執行的 QA 紀錄</h2><p class="section-intro">這裡的結論來自本專案檔案驗證；另以 Chromium 做了 14 項瀏覽器 DOM 操作測試，14 項通過，詳見 <code>logs/browser_tests.json</code>。因測試環境限制，未驗證公開部署後的跨頁導覽。</p><div class="glass" style="padding:24px"><table class="audit-table"><thead><tr><th>檢查項目</th><th>故障注入測試</th><th>修正後</th></tr></thead><tbody>__QROWS__</tbody></table><p class="muted" style="font-size:13px;margin-top:18px">檢查方法：Python 程式比對資料清單、wiki refs、來源追溯及 HTML 輸出；不等同模型回答正確率的統計實驗。</p></div></section><section class="section"><h2 class="section-title">03 / 問題、修正與反思</h2><div class="feature-grid"><div class="feature"><div class="eyebrow">MOST FRAGILE NODE</div><h3>Wiki → Slide 的引用對應</h3><p>整理成簡單投影片時，最容易只留下敘述而漏掉來源 ID，讓讀者無法回查。這次在第一次檢查的故障注入測試中，確實抓到一筆刻意漏放的來源 ID。</p></div><div class="feature"><div class="eyebrow">SHIFT LEFT</div><h3>把檢查提前到大綱階段</h3><p>原本打算在完成 HTML 後檢查引用；改成在投影片資料表建立時，就要求每張教學頁有 Wiki 對應和合法的來源 ID。</p></div><div class="feature"><div class="eyebrow">GRAPH CHANGE</div><h3>新增 Source Audit 節點</h3><p>每張投影片生成前先驗證引用，未通過就返回調整內容或補來源，避免渲染完成才逐張返工。</p></div></div><div class="glass" style="padding:28px;margin-top:22px"><div class="eyebrow">WHY THIS GRAPH?</div><h3>把來源錯誤與呈現錯誤分開處理</h3><p class="muted">來源不夠時，補充資料；理解有誤時，修改 Wiki；引用錯誤時，修正大綱；畫面或互動錯誤時，重做 HTML。讓每個失敗回到最接近原因的節點，避免用一句「再生成一次」取代除錯。</p></div></section></main>'''
checks=[('來源數量 ≥ 5','sources_min_5'),('所有來源代號不重複','source_unique'),('每篇 Wiki 有合法來源','wiki_source_links'),('每張簡報引用有效 Wiki','slide_wiki_refs'),('每張簡報引用有效來源','slide_source_refs'),('簡報來源與 Wiki 支持對應','slide_grounding'),('HTML 可生成並包含 14 張','html_generated')]
before=Q.get('before',{});after=Q.get('after',{})
rows=''.join(f'<tr><td>{label}</td><td class="{"status-pass" if before.get(k,False) else "status-fail"}">{"PASS" if before.get(k,False) else "FAIL"}</td><td class="{"status-pass" if after.get(k,False) else "status-fail"}">{"PASS" if after.get(k,False) else "FAIL"}</td></tr>' for label,k in checks)
(R/'workflow.html').write_text(layout('Loop / Graph 與 QA',report.replace('__QROWS__',rows),'workflow'),encoding='utf-8')
print('Generated: index.html, wiki.html, slides.html, workflow.html')
